import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testMaxInts() {
        Assert.assertEquals(95, findMax(listOf(85, 92, 78, 95, 88)))
    }

    @Test
    fun testMaxStrings() {
        Assert.assertEquals("cherry", findMax(listOf("apple", "cherry", "banana")))
    }

    @Test
    fun testMaxDoubles() {
        Assert.assertEquals(9.8, findMax(listOf(3.14, 2.72, 9.8, 1.41)), 0.001)
    }

    @Test
    fun testMaxSingleElement() {
        Assert.assertEquals(42, findMax(listOf(42)))
    }

    @Test
    fun testMaxWithDuplicates() {
        Assert.assertEquals(100, findMax(listOf(100, 50, 100, 75)))
    }
}
